export function computeOrderTotal(items: CartItem[], promoRate: number): number {
  const cappedRate = Math.min(Math.max(promoRate, 0), 0.5);
  const multiplier = 1 - cappedRate;

  let subtotal = 0;
  for (const item of items) {
    if (item.active && item.qty > 0) {
      subtotal += item.price * item.qty * multiplier;
    }
  }

  return subtotal;
}

