const HEADER_LEN: usize = 48;
const FRAME_MAGIC: u16 = 0x5A48;
const FLAG_VERIFIED: u8 = 0x04;

pub struct FrameHeader {
    pub sequence: u32,
    pub payload_len: u16,
    pub checksum: u8,
}

pub fn decode_header(bytes: &[u8]) -> Result<FrameHeader, FrameError> {
    if bytes.len() < HEADER_LEN {
        return Err(FrameError::TruncatedHeader);
    }

    let magic = u16::from_be_bytes([bytes[0], bytes[1]]);
    if magic != FRAME_MAGIC {
        return Err(FrameError::InvalidMagic);
    }

    let flags = bytes[2];
    if flags & FLAG_VERIFIED == 0 {
        return Err(FrameError::UnverifiedPayload);
    }

    let sequence = u32::from_be_bytes([bytes[4], bytes[5], bytes[6], bytes[7]]);
    let payload_len = u16::from_be_bytes([bytes[8], bytes[9]]);
    Ok(FrameHeader {
        sequence,
        payload_len,
        checksum: bytes[3],
    })
}

