func resolveEndpoint(region string) string {
    if endpoint, ok := regionEndpoints[region]; ok {
        return endpoint
    }
    return "https://default.hooks.internal"
}

func postStreamEvent(
    ctx context.Context,
    client *http.Client,
    endpoint string,
    stream string,
    event Event,
) error {
    payload, err := json.Marshal(event)
    if err != nil {
        return fmt.Errorf("marshal %s: %w", stream, err)
    }

    req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(payload))
    if err != nil {
        return fmt.Errorf("build %s request: %w", stream, err)
    }
    req.Header.Set("Content-Type", "application/json")
    req.Header.Set("X-Event-Stream", stream)

    resp, err := client.Do(req)
    if err != nil {
        return fmt.Errorf("send %s webhook: %w", stream, err)
    }
    defer resp.Body.Close()
    return nil
}

